INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('d3077932-428b-1fac-4457-19db1da4a458', 'VERAL Electric 5 metrli o''lchov tasmasi (Ruletka)', 'veral-electric-5m-ruletka', 'VERAL Electric — professional o''lchov ishlari uchun yuqori sifatli 5 metrli ruletka. Lentasining qalinligi 19mm, aniq va yorqin shkalaga ega. Ergonomik kauchuk korpusi sirpanib ketishdan va zarbadan himoya qiladi. Avtomatik qulflanish funksiyasi ishlashni osonlashtiradi.', 20000, 30000, 33, 'b244b549-7683-0d68-276c-ec76105164a1', 'VERAL electric', 50, 'VRL-5M-19', 5, 12, '/products/veral_5m.jpg', true, false, true, '{"O''lchov uzunligi":"5 metr","Tasma kengligi":"19 mm","Material":"ABS plastik + Kauchuk","Korpus xususiyati":"Zarbaga chidamli","Avto-qulflash":"Mavjud"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('04187f9b-d08e-b25e-5b83-d7bbbfe34f8d', 'BIYOTI BYT-2602 Perforator (Rotary Hammer)', 'biyoti-byt-2602-perforator', 'BIYOTI BYT-2602 — uy va yarim professional qurilish ishlari uchun mo''ljallangan kuchli perforator (otboynik). U 3 ta rejimda ishlaydi: burg''ulash, zarbli burg''ulash va o''yish. Komplektda mustahkam plastik keys, qo''shimcha tutqich, chuqurlik o''lchagich, 3 ta SDS-plus pichoq va 2 ta iskana (zubilo) mavjud. Yuqori sifatli Yevropa standarti asosida ishlab chiqarilgan.', 460000, 520000, 11, 'e02986ab-8b78-f9cf-704e-b3796fcf12dc', 'BIYOTI', 25, 'BYT-2602', 4.8, 15, '/products/biyoti_byt2602.png', true, false, true, '{"Ish rejimlari":"3 ta rejim (Teshish, Zarbali teshish, O''yish)","Patron turi":"SDS-Plus","Komplektatsiya":"Keys, 3 ta sverlo, 2 ta zubilo","Standart":"Made for EURO","Quvvat turi":"Tarmoqli (220V)"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('3b16d551-5c26-0d6c-e2c5-196850d64cd2', 'ADEGSO 10289 Kantselyariya/Oboy pichog''i', 'adegso-oboy-pichogi-10289', 'ADEGSO (Model: 10289) — qog''oz, karton, oboy va boshqa materiallarni kesish uchun mo''ljallangan yuqori sifatli ''ustalar tanlovi'' pichog''i. Pichoqning uchini sindirib, doimiy o''tkir holatda ishlatish mumkin (Snap-off blade). Korpusi qulay ushlash uchun maxsus teksturali dizaynga ega.', 10000, 15000, 33, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'ADEGSO', 100, 'ADG-10289', 4.9, 8, '/products/adegso_knife_10289.png', true, false, true, '{"Pichoq turi":"Sindirib yangilanadigan (Snap-off)","Vazifasi":"Oboy, qog''oz, karton kesish","Korpus materiali":"Qattiq plastmassa + rezina qo''shimchalar","Model":"10289"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('78f84cc9-2fff-33ac-9577-c6f9f7072fbb', 'ADEGSO 10287 Buklanadigan Oboy pichog''i (Raskladnoy)', 'adegso-oboy-pichogi-buklanadigan-10287', 'ADEGSO (Model: 10287) — ixcham va qulay, buklanadigan (raskladnoy) oboy pichog''i. Pichoq uchi trapez shaklida bo''lib, o''ta o''tkir kesish xususiyatiga ega. Komplektda qo''shimcha zaxira lezviyalar saqlanadigan kichik kassetasi ham bor. ''Ustalar tanlovi'' toifasiga kiruvchi yuqori sifatli asbob.', 30000, 40000, 25, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'ADEGSO', 75, 'ADG-10287', 5, 12, '/products/adegso_knife_10287.png', true, false, true, '{"Pichoq turi":"Buklanadigan (Raskladnoy / Yig''iluvchi)","Vazifasi":"Oboy, qog''oz, gipsokarton, linoleum kesish","Komplektatsiya":"Pichoq + Zaxira pichoqchalar (lezviya)","Model":"10287"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('e9b54450-9185-2fc3-caaf-fc28bb5e0fa5', 'RUR R1817 Indikatorli Otvyortka (Tok tekshirgich)', 'rur-r1817-indikatorli-otvyortka', 'RUR (Model: R1817) — elektr toki bor-yo''qligini xavfsiz va aniq tekshirish uchun mo''ljallangan indikatorli otvyortka. Uch qismi yuqori sifatli qotishmadan qilingan bo''lib, oddiy otvyortka sifatida ham ishlatish mumkin. Chirog''i yorqin yonadi va tutqichi qulay plastikdan ishlangan.', 12000, 18000, 33, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 120, 'RUR-R1817', 4.8, 22, '/products/rur_r1817.png', true, false, true, '{"Turi":"Indikatorli (Tester)","Vazifasi":"Elektr toki mavjudligini tekshirish","Model":"R1817","Material":"Izolyatsiyalangan plastmassa va po''lat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('58408080-d50f-2d32-7746-c29edd9a4b6c', 'RUR R3039 Krokodil (Ploskogubsi / Klyuch)', 'rur-r3039-krokodil-ploskogubsi', 'RUR (Model: R3039) — santexnika va mexanika ishlari uchun mo''ljallangan universal sozlanuvchi qisqich (krokodil / gazoviy klyuch). Turli o''lchamdagi truba va gaykalarni mahkam siqish uchun ko''p pog''onali sozlash mexanizmiga ega. Yuqori mustahkamlikdagi po''latdan ishlangan, tutqichi sirpanmaydigan qoplamali.', 95000, 120000, 21, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 60, 'RUR-R3039', 5, 18, '/products/rur_r3039.png', true, false, true, '{"Turi":"Sozlanuvchi qisqich (Krokodil)","Model":"R3039","Material":"Yuqori sifatli karbonli po''lat","Tutqich":"Sirpanmaydigan, ergonomik qoplama","Qo''llanilishi":"Santexnika, mexanika, ta''mirlash"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('2ceeac26-9e1f-9bc2-5645-9230fcc1199e', 'EAFIXS Bog'' qaychisi (Sekator / Pruning shears)', 'eafixs-bog-qaychisi-sekator', 'EAFIXS Professional Tools — daraxt shoxlari, uzum toklarini va gul butalarini kesish uchun mo''ljallangan yuqori sifatli sekator. Qalinligi 20mm gacha bo''lgan shoxlarni osonlik bilan qirqadi. SKS+ sifatli po''latdan ishlangan, tutqichi ergonomik va sirpanmaydi. Sifat kafolati (Industrial / TUV GS).', 55000, 70000, 21, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'EAFIXS', 80, 'EAF-SEKATOR', 4.9, 14, '/products/eafixs_sekator.png', true, false, true, '{"Kesish diametri":"20 mm gacha","Pichoq materiali":"SKS+ Yuqori sifatli po''lat","Vazifasi":"Bog''dorchilik, shoxlarni kesish","Sifat standarti":"TUV GS / Industrial","Tutqich":"Sirpanmaydigan qoplama, qulflanuvchi"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('92a63c05-3e39-5b42-5470-a50d68303244', 'RUR R1816 Elektron Indikatorli Otvyortka (Raqamli Displey)', 'rur-r1816-elektron-indikator', 'RUR (Model: R1816) — tok kuchlanishini (12-250V) raqamli displeyda aniq ko''rsatuvchi elektron indikator-otvyortka. Dark Vision funksiyasi tufayli qorong''i joylarda ham ko''rsatkichlarni bemalol o''qish mumkin. Elektriklar va uy ustalari uchun juda qulay va zamonaviy asbob.', 40000, 55000, 27, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 90, 'RUR-R1816', 4.9, 17, '/products/rur_r1816.png', true, false, true, '{"Turi":"Elektron indikator (Tester)","Kuchlanish diapazoni":"AC/DC 12V-250V","Displey":"Raqamli LCD (Dark Vision)","Vazifasi":"Tokni va kuchlanishni tekshirish","Model":"R1816"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('a41bf5c3-1071-d79d-7e7c-979203d34f54', 'RUR R1813 Raqamli Indikatorli Otvyortka (Digital Voltage Tester)', 'rur-r1813-raqamli-indikator', 'RUR (Model: R1813) — tok kuchlanishini LCD displeyda ko''rsatadigan raqamli indikator-tester. Oddiy indikatorlarga qaraganda qulayroq va aniqroq tekshiradi (12V-250V). Ixcham dizayn va sifatli RUR Tools mahsuloti.', 30000, 40000, 25, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 150, 'RUR-R1813', 4.8, 21, '/products/rur_r1813.png', true, false, true, '{"Turi":"Raqamli indikator (Voltage Tester)","Kuchlanish diapazoni":"12V - 250V AC/DC","Displey":"LCD displey","Model":"R1813"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('53f0f327-0821-3200-3a46-61e3aeb2a6ed', 'ROMA TOOLS HT-535 Qurilish Quloqchini (Naushnik)', 'roma-tools-ht535-qurilish-quloqchini', 'ROMA TOOLS (Model: HT-535) — baland shovqinli qurilish, ta''mirlash va ishlab chiqarish sexlarida ishlash uchun mo''ljallangan himoya quloqchini. Quloqni mukammal yopib turuvchi yumshoq yostiqchalari va boshga moslab sozlanuvchi qulay yoyi (dujkasi) bor. Eshitish qobiliyatini asrash uchun muhim himoya vositasi.', 35000, 45000, 22, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'ROMA TOOLS', 200, 'RMA-HT535', 5, 34, '/products/roma_ht535.png', true, false, true, '{"Turi":"Qurilish himoya quloqchini (Shumoizolyatsiya)","Model":"HT-535","Xususiyati":"Sozlanuvchi yoy, yumshoq yostiqchalar","Vazifasi":"Baland shovqindan himoya qilish"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('b8c53401-df65-373f-595a-285d78e76d4a', 'ADEGSO AD-50511 Otvyortkalar to''plami (8 dona)', 'adegso-ad50511-otvyortkalar-toplami', 'ADEGSO (Model: 50511) — ''Ustalar tanlovi'' qatoriga kiruvchi 8 ta har xil o''lchamdagi professional otvyortkalar to''plami. Katta, o''rtacha va kalta (bochka) otvyortkalarni o''z ichiga oladi. Magnitlangan uchi, ergonomik va sirpanmaydigan tutqichlari bilan ishlash uchun juda qulay.', 95000, 120000, 21, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'ADEGSO', 50, 'ADG-50511', 4.9, 14, '/products/adegso_screwdrivers_50511.png', true, false, true, '{"To''plam tarkibi":"8 dona (Katta, kichik, kalta otvyortkalar)","Uch qismi":"Magnitlangan (krestovoy va ploskiy)","Tutqich":"Sirpanmaydigan kauchuk + plastmassa","Model":"AD-50511"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('349ce609-2ac8-dc2e-5313-1c553ef0286e', 'ADEGSO AD-50513 Tok o''tkazmaydigan Otvyortkalar to''plami (5 dona)', 'adegso-ad50513-dielektrik-otvyortkalar', 'ADEGSO (Model: 50513) — ''Ustalar tanlovi'' qatoriga kiruvchi 5 ta har xil o''lchamdagi dielektrik (tok o''tkazmaydigan) otvyortkalar to''plami. Elektromontaj ishlari uchun maxsus mo''ljallangan bo''lib, xavfsiz ishlashni ta''minlaydi. Ergonomik qizil-sariq tutqich va to''liq izolyatsiya qilingan stervenga ega.', 75000, 95000, 21, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'ADEGSO', 60, 'ADG-50513', 5, 18, '/products/adegso_screwdrivers_50513.png', true, false, true, '{"To''plam tarkibi":"5 dona (Krestovoy va ploskiy)","Izolyatsiya":"Dielektrik (tok o''tkazmaydi)","Qo''llanilishi":"Elektromontaj va tok ostida ishlash","Model":"AD-50513"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('e793f5aa-9d2b-9f1d-26fa-63294f647d78', 'ADEGSO AD-50211 Universal Hop-Shop Klyuch (2 dona)', 'adegso-ad50211-hop-shop-klyuch', 'ADEGSO (Model: 50211) — ''Ustalar tanlovi'' qatoridagi universal klyuchlar to''plami (Hop-Shop klyuch / Snap''n Grip). To''plamda 2 ta har xil o''lchamdagi klyuch bor bo''lib, ular har qanday shakldagi (kvadrat, dumaloq, oltiburchak) gayka va trubkalarni avtomatik ravishda mahkam qisib oladi. Santexnika va avto ta''mirlash uchun juda qulay.', 55000, 70000, 21, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'ADEGSO', 80, 'ADG-50211', 4.8, 22, '/products/adegso_wrench_50211.png', true, false, true, '{"To''plam tarkibi":"2 dona (Katta va kichik klyuch)","Turi":"Universal o''zi qisuvchi klyuch","Qo''llanilishi":"Santexnika, mexanika, ro''zg''or ishlari","Model":"AD-50211"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('0a176e16-f80d-89fc-d012-303b9927c712', 'RUR R3038 Krokodil (Sozlanuvchi Ploskogubsi)', 'rur-r3038-krokodil', 'RUR (Model: R3038) — yuqori sifatli ''Krokodil'' (sozlanuvchi ploskogubsi / water pump pliers). Santexnika ishlari va trubalarni qisish uchun juda qulay. Qattiq qotishmali jag''lari va sirpanmaydigan ko''k-kulrang tutqichlari bilan ishonchli ushlashni ta''minlaydi. Turli o''lchamlarga moslashish uchun ko''p pog''onali mexanizmga ega.', 65000, 85000, 23, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 75, 'RUR-R3038', 5, 16, '/products/rur_krokodil_r3038.png', true, false, true, '{"Turi":"Sozlanuvchi qisqich (Krokodil)","Qo''llanilishi":"Santexnika va mexanika","Material":"Yuqori chidamli qotishma po''lat","Model":"R3038"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('dcc5b15a-5165-b9bd-b3a4-de2f2dcda90f', 'RUR R3049 Kabel Tozalagich (Stripping Crimping Pliers)', 'rur-r3049-kabel-tozalagich', 'RUR (Model: R3049) — elektr simlari va kabellarni izolyatsiyasidan tozalash hamda siqish (krimpovka) uchun mo''ljallangan maxsus asbob. Elektriklar uchun juda zarur bo''lgan bu asbob simning ichiga shikast yetkazmasdan sirtini tozalaydi. Sirpanmaydigan qulay tutqichga ega.', 85000, 110000, 22, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 85, 'RUR-R3049', 4.9, 24, '/products/rur_stripper_r3049.png', true, false, true, '{"Turi":"Kabel tozalagich va siquvchi (Stripper)","Qo''llanilishi":"Elektromontaj, simlarni tozalash","Material":"Yuqori sifatli po''lat","Model":"R3049"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('e808288d-c6aa-fc31-cd6a-234c37cc32b1', 'RUR R2344 Kabel Tozalagich (Wire Stripper)', 'rur-r2344-kabel-tozalagich', 'RUR (Model: R2344) — sim va kabellarni tez va aniq tozalash uchun mo''ljallangan qulay asbob. Simning turli diametrlariga moslashtirilgan o''yiqlari yordamida ishlash juda oson. O''tkir po''lat pichog''i va rezinali qulay tutqichi bilan ajralib turadi.', 45000, 60000, 25, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 120, 'RUR-R2344', 4.8, 19, '/products/rur_stripper_r2344.png', true, false, true, '{"Turi":"Kabel tozalagich (Wire Stripper)","Qo''llanilishi":"Sim izolyatsiyasini tozalash","Model":"R2344","Material":"Maxsus ishlov berilgan po''lat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('cf4bcf34-6c21-59c1-9349-3bba9698f1de', 'ADEGSO 30W Payalnik (Soldering Iron)', 'adegso-ad40221-payalnik-30w', 'ADEGSO (Model: 40221) — elektronika va mayda ta''mirlash ishlari uchun mo''ljallangan 30 Vt quvvatli sifatli payalnik (kavshar). Tez qiziydi va issiqlikni yaxshi ushlaydi. ''Ustalar tanlovi'' toifasiga kiruvchi ishonchli va xavfsiz elektr asbob.', 65000, 85000, 23, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'ADEGSO', 90, 'ADG-40221', 4.8, 15, '/products/adegso_soldering_40221.png', true, false, true, '{"Quvvati":"30 Vt (Watt)","Turi":"Elektr payalnik (Soldering iron)","Qo''llanilishi":"Elektronika ta''mirlash","Model":"AD-40221"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('cd30667b-77e5-f75a-cb2f-47c6918f7e43', 'BIYOTI BYT-1337 Devor Kesuvchi (Shtroborez)', 'biyoti-byt1337-shtroborez', 'BIYOTI BYT-1337 — professional devor kesuvchi (shtroborez). Elektr simlari, trubalar va kabellar uchun devorlarda ariqcha (shtroba) ochishga mo''ljallangan. 1500 Vt quvvatli kuchli motor, 125mm disk va qulay dizayn ishlashni osonlashtiradi. Suv ulab ishlash imkoniyati mavjud (chang chiqarmaslik uchun).', 1100000, 1300000, 15, 'df016ee5-10bd-8b03-ae39-ac78a77b9b27', 'BIYOTI', 12, 'BYT-1337', 4.9, 11, '/products/biyoti_shtroborez_byt1337.png', true, false, true, '{"Quvvati":"1500 Vt (Watt)","Disk diametri":"125 mm","Turi":"Devor kesuvchi (Shtroborez)","Vazifasi":"Beton, g''isht va tosh kesish","Model":"BYT-1337"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('9bea2d5b-c4f0-ae20-1ac6-b9d425ee8945', 'BIYOTI 16.8V Li-ION Akkumulyator (Battery Pack)', 'biyoti-16-8v-li-ion-akkumulyator', 'BIYOTI — 16.8V kuchlanishli litiy-ion (Li-ION) akkumulyator blok. BIYOTI brendining shurupovyortlari va boshqa simsiz asboblari uchun maxsus (Power Share) mo''ljallangan. 100% original, uzoq muddat xizmat qiladi va tez quvvat oladi.', 65000, 85000, 23, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'BIYOTI', 200, 'BYT-BAT-168V', 4.8, 42, '/products/biyoti_battery_16v.png', true, false, true, '{"Turi":"Li-ION Akkumulyator","Kuchlanish":"16.8V","Mosligi":"BIYOTI asboblari uchun","Sifat":"100% Original"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('de3fcd2d-4d7d-df77-77b9-8d367d2c89af', 'TEH TH8516 Otboynik (Отбойный молоток) 50J', 'teh-th8516-otboynik-50j', 'TEH (Model: TH8516) — og''ir qurilish va buzish ishlari uchun mo''ljallangan juda kuchli otboynik (perforator). Zarba kuchi 50 Joul bo''lib, beton, asfalt va toshlarni osongina maydalaydi. Zarbalar chastotasi daqiqasiga 1900 marta. Sanoat darajasidagi asbob.', 2250000, 2600000, 13, 'e02986ab-8b78-f9cf-704e-b3796fcf12dc', 'TEH', 10, 'TH-8516', 5, 8, '/products/teh_otboynik_th8516.png', true, false, true, '{"Zarba kuchi":"50 J","Zarbalar soni":"1900 zarba/daq","Quvvati":"1600 Vt (rasmda 160W yozilgani xato bo''lishi mumkin)","Turi":"Og''ir otboynik (Buzuvchi bolg''a)","Tarmoq":"220V/50HZ"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('6676aa46-408b-4fd0-41fc-d5a2d2d2e2d8', 'BIYOTI Ko''p diskli Devor Kesuvchi (Multi-disk Shtroborez)', 'biyoti-multidisk-shtroborez', 'BIYOTI — bir vaqtning o''zida bir nechta olmosli disklar (multi-disk) yordamida ishlaydigan og''ir va professional devor kesuvchi (shtroborez). Keng va chuqur ariqchalarni (shtroba) bir urishda ochish uchun mo''ljallangan. Beton va g''ishtni tez maydalaydi, chang chiqarmaslik uchun maxsus himoya qoplamiga ega.', 1600000, 1850000, 13, 'df016ee5-10bd-8b03-ae39-ac78a77b9b27', 'BIYOTI', 8, 'BYT-SHTR-MULTI', 5, 12, '/products/biyoti_multidisk_shtroborez.png', true, false, true, '{"Disklar soni":"Ko''p diskli (Multi-disk)","Turi":"Professional shtroborez (Devor kesuvchi)","Vazifasi":"Betonda chuqur va keng ariqcha ochish","Sifat":"Sanoat darajasi"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('2374f3e3-61b5-a6ac-3163-b2238602751c', 'BIYOTI BYT-12001 Himoya Perchatkasi (Ishchi Qo''lqop)', 'biyoti-byt12001-perchatka', 'BIYOTI (Model: BYT-12001) — qurilish va ta''mirlash ishlari uchun mo''ljallangan yuqori sifatli himoya qo''lqopi (perchatka). Kaft qismi maxsus sirpanmaydigan ko''k qoplama (rezina/lateks) bilan ishlangan bo''lib, asboblarni mustahkam ushlash imkonini beradi. O''lchami: 10/XL.', 8000, 12000, 33, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'BIYOTI', 500, 'BYT-12001', 4.9, 55, '/products/biyoti_gloves_12001.png', true, false, true, '{"O''lchami":"10 / XL","Turi":"Himoya ishchi qo''lqopi","Material":"Mato va sirpanmaydigan qoplama","Model":"BYT-12001"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('d07cb9e0-e883-4cb7-0023-e884f185d7ec', 'BIYOTI 6" Drel uchun Arra Nasadka (Mini Chainsaw Attachment)', 'biyoti-drel-arra-nasadka-6', 'BIYOTI 6 dyuymli zanjirli arra nasadkasi. Ushbu nasadka yordamida oddiy drel yoki shurupovyortni kichik zanjirli arraga aylantirish mumkin. Daraxt shoxlarini kesish, o''tin tayyorlash va bog'' ishlari uchun juda qulay va ixcham yechim. ''Strong Power'' dizayni barqaror ishlashni ta''minlaydi.', 65000, 85000, 23, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'BIYOTI', 85, 'BYT-CHAIN-6', 4.8, 36, '/products/biyoti_chainsaw_attachment_6.png', true, false, true, '{"O''lchami":"6 dyuym (6\")","Turi":"Drel uchun arra nasadka (Attachment)","Mosligi":"Har qanday drel va shurupovyort","Vazifasi":"Yog''och va shoxlarni kesish"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('82406c4d-4076-1665-acb9-19992f176523', 'RUR R3122 Bog'' Qaychisi (Sekator)', 'rur-r3122-sekator', 'RUR (Model: R3122) — bog''dorchilik ishlari uchun mo''ljallangan universal bog'' qaychisi (sekator). Daraxt shoxlari, tok va gullarni kesish uchun juda qulay. O''tkir po''lat tig''i va yengil prujinali mexanizmi tufayli qo''lni charchatmaydi. Sifatli va uzoq muddat xizmat qiladigan asbob.', 35000, 45000, 22, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 150, 'RUR-R3122', 4.8, 31, '/products/rur_sekator_r3122.png', true, false, true, '{"Turi":"Bog'' qaychisi (Sekator)","Model":"R3122","Material":"Yuqori sifatli po''lat","Vazifasi":"Shox va novdalarni kesish"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('6e312eb6-10c7-0cb7-7ad4-4dceac806cf5', 'OCKEAN Yig''ma Torx (Yulduzcha) Kalitlar To''plami', 'ockean-yigma-torx-kalitlar', 'OCKEAN brendidan ixcham va yig''iladigan Torx (yulduzcha) kalitlar to''plami. Cho''ntakbop dizayn, ergonomik rezina tutqich va yuqori sifatli po''latdan ishlangan kalitlar. Usta va havaskorlar uchun velosiped, elektronika va maishiy texnikalarni ta''mirlashda ajralmas yordamchi.', 50000, 65000, 23, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'OCKEAN', 200, 'OCK-TORX-FOLD', 4.9, 45, '/products/ockean_folding_torx.png', true, false, true, '{"Turi":"Yig''ma kalitlar to''plami (Folding Keys)","Uchi turi":"Torx (Yulduzsimon)","Material":"Krom-vanadiy po''lat (Cr-V)","Tutqich":"Sirpanmaydigan rezina-plastik"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('1b8f8f43-9b52-5636-bdc2-f9df0c992b2e', 'OCKEAN 5 metrli O''lchov Tasmasi (Ruletka)', 'ockean-5m-ruletka', 'OCKEAN Quality Tools — zamonaviy shaffof korpusli 5 metrli o''lchov tasmasi (ruletka). Lentasining qalinligi 19mm, ixcham dizayn (Labor saving 50%) va qulay qulflash (Lock) tugmasiga ega. Usta va quruvchilar uchun mustahkam va aniq o''lchov vositasi.', 27000, 35000, 22, 'b244b549-7683-0d68-276c-ec76105164a1', 'OCKEAN', 120, 'OCK-RUL-5M', 4.8, 24, '/products/ockean_ruletka_5m.jpg', true, false, true, '{"Uzunligi":"5 metr","Tasma kengligi":"19 mm","Korpus":"Shaffof (Transparent) plastik","Qulflash":"Fiksator tugmasi mavjud"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('f71d14f0-a36f-6def-78fb-1f9537f3a4a7', 'OCKEAN Lazerli O''lchov Masofasi (Lazerniy Metr) 100M', 'ockean-lazer-metr-100m', 'OCKEAN — professional lazerli masofa o''lchagich (lazerniy metr / ruletka). 100 metrgacha bo''lgan masofani aniq va tez o''lchab beradi. Maydon, hajm va Pifagor teoremasi bo''yicha hisoblash funksiyalariga ega. Katta LCD displey va suv/changdan himoyalangan korpus.', 360000, 450000, 20, 'b244b549-7683-0d68-276c-ec76105164a1', 'OCKEAN', 50, 'OCK-LASER-100', 4.9, 18, '/products/ockean_laser_meter_100m.png', true, false, true, '{"O''lchov masofasi":"100 metr","Turi":"Lazerli masofa o''lchagich (Lazerniy ruletka)","Ekran":"Raqamli LCD","Qo''shimcha funksiyalar":"Maydon (kvadrat), Hajm (kub) hisoblash"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('b7073a2a-ef3b-04f6-8b4f-18965d5efcc8', 'OCKEAN Zarbli Otvyortka (Krestli)', 'ockean-zarbli-otvyortka', 'OCKEAN — og''ir ish sharoitlari uchun mo''ljallangan professional zarbli otvyortka (udarnaya otvyortka). Qotib qolgan yoki zanglagan burama mixlarni (shuruplarni) bolg''a yordamida urib bo''shatish uchun metall o''zakka ega. Rezina va plastik aralashmali tutqichi sirpanishni oldini oladi. Krestli (Phillips) uchi yuqori sifatli po''latdan ishlangan.', 25000, 35000, 28, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'OCKEAN', 250, 'OCK-OTV-UDAR', 4.8, 52, '/products/ockean_udarnaya_otvertka.jpg', true, false, true, '{"Turi":"Zarbli (Udarniy) otvyortka","Uchi turi":"Krestli (Phillips / PH)","Material":"Krom-vanadiy po''lat (Cr-V)","Xususiyati":"Bolg''a bilan urish uchun metall o''zak"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('d87e1301-1b4c-f589-d4ad-fa6970dc91e1', 'OCKEAN PH2 S2 Krestli Otvyortka', 'ockean-ph2-s2-otvyortka', 'OCKEAN markali yuqori sifatli (S2 po''lat) krestli (PH2) otvyortka. Uy, avtomobil va elektronika ta''mirlash ishlari uchun ideal. Ergonomik ikki komponentli (rezina va plastik) tutqichi qo''lda juda qulay yotadi va sirpanmaydi. Magnitli uchga ega.', 25000, 32000, 21, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'OCKEAN', 300, 'OCK-PH2-S2', 4.9, 41, '/products/ockean_ph2_otvertka.jpg', true, false, true, '{"Turi":"Krestli (Phillips) otvyortka","O''lchami":"PH2","Material":"S2 Sanoat po''lati","Xususiyati":"Magnitli uch va sirpanmas tutqich"}'::jsonb) ON CONFLICT (id) DO NOTHING;
